#include "mesh_scan.hpp"

#include <algorithm>

#include "volumetric_kit/core/vulkan/command_batch.hpp"
#include "volumetric_kit/core/vulkan/compute_util.hpp"
#include "volumetric_kit/core/vulkan/device.hpp"
#include "volumetric_kit/core/vulkan/vulkan.hpp"

// Embedded SPIR-V (generated by vgrid_embed_shaders onto a PRIVATE include
// path).
#include "mesh_scan_add_comp.spv.hpp"
#include "mesh_scan_counts_comp.spv.hpp"
#include "mesh_scan_sums_comp.spv.hpp"

namespace volumetric_kit::grid::voxelize::detail {
namespace {

constexpr std::uint32_t kLanes = 256;

// Mirrors the push block of mesh_scan_*.comp under scalar layout.
struct ScanPush {
  std::uint32_t size;
  std::uint32_t first_group;
};
static_assert(sizeof(ScanPush) == 8, "ScanPush layout drift");

std::uint32_t group_count(std::uint32_t items) {
  return core::group_count(items, kLanes);
}

}  // namespace

MeshScan::~MeshScan() = default;

core::Result<std::unique_ptr<MeshScan>> MeshScan::create(
    core::Device& device, core::Allocator& allocator, const char* name) {
  std::unique_ptr<MeshScan> scan(new MeshScan());
  scan->device_ = &device;
  scan->allocator_ = &allocator;
  scan->name_ = name;
  const VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0,
                                  sizeof(ScanPush)};
  core::KernelSetBuilder kb(device);
  VKC_TRY(kb.add(scan->counts_, name, vgrid_mesh_scan_counts_comp_spv,
                 vgrid_mesh_scan_counts_comp_spv_size, 2, &range));
  for (core::ComputeKernel& kernel : scan->sums_) {
    VKC_TRY(kb.add(kernel, name, vgrid_mesh_scan_sums_comp_spv,
                   vgrid_mesh_scan_sums_comp_spv_size, 2, &range));
  }
  for (core::ComputeKernel& kernel : scan->add_) {
    VKC_TRY(kb.add(kernel, name, vgrid_mesh_scan_add_comp_spv,
                   vgrid_mesh_scan_add_comp_spv_size, 2, &range));
  }
  VKC_ASSIGN(scan->pool_, kb.build());
  VkPhysicalDeviceProperties props{};
  vkGetPhysicalDeviceProperties(device.physical_device(), &props);
  scan->max_workgroup_count_x_ = props.limits.maxComputeWorkGroupCount[0];
  scan->max_storage_buffer_range_ = props.limits.maxStorageBufferRange;
  return scan;
}

core::Status MeshScan::prepare(const core::Buffer& values,
                               std::uint32_t size) {
  // 256-way hierarchy: even one leaf group is scanned once, leaving its
  // exclusive prefix zero and its aggregate in a separate root. At most
  // three summary passes cover every uint32-sized input.
  level_sizes_ = {};
  level_sizes_[0] = group_count(size);
  root_level_ = 0;
  do {
    level_sizes_[root_level_ + 1] = group_count(level_sizes_[root_level_]);
    ++root_level_;
  } while (level_sizes_[root_level_] > 1);
  for (std::size_t i = 0; i <= root_level_; ++i) {
    VKC_TRY(core::ensure_device_scratch(
        *device_, *allocator_, levels_[i],
        VkDeviceSize(std::max(level_sizes_[i], 1u)) * kSummaryBytes,
        max_storage_buffer_range_, name_));
  }
  const auto bind = [](const core::ComputeKernel& kernel, std::uint32_t binding,
                       const core::Buffer& buffer) {
    kernel.set.write_storage_buffer(binding, buffer.handle(), 0, VK_WHOLE_SIZE);
  };
  bind(counts_, 0, values);
  bind(counts_, 1, levels_[0]);
  for (std::size_t i = 0; i < root_level_; ++i) {
    bind(sums_[i], 0, levels_[i]);
    bind(sums_[i], 1, levels_[i + 1]);
    if (i + 1 < root_level_) {
      bind(add_[i], 0, levels_[i]);
      bind(add_[i], 1, levels_[i + 1]);
    }
  }
  return {};
}

core::Status MeshScan::record(core::CommandBatch& batch, std::uint32_t size,
                              core::GpuStageScope* stage) const {
  // A large count is scanned in dispatch slices rather than refused on a
  // device with a low maxComputeWorkGroupCount[0]. The sets stay unchanged
  // within the batch; only the push constants change per slice.
  const std::uint32_t max_groups = max_workgroup_count_x_;
  const auto pass = [&](const core::ComputeKernel& kernel,
                        std::uint32_t items) -> core::Status {
    const std::uint32_t groups = group_count(items);
    for (std::uint32_t first_group = 0; first_group < groups;) {
      const std::uint32_t n = std::min(groups - first_group, max_groups);
      const ScanPush push{items, first_group};
      VKC_TRY(batch.dispatch(kernel, &push, sizeof(push), n, max_groups,
                             stage));
      first_group += n;
    }
    return {};
  };
  VKC_TRY(pass(counts_, size));
  for (std::size_t i = 0; i < root_level_; ++i) {
    VKC_TRY(pass(sums_[i], level_sizes_[i]));
  }
  for (std::size_t i = root_level_ - 1; i > 0; --i) {
    VKC_TRY(pass(add_[i - 1], level_sizes_[i - 1]));
  }
  return {};
}

}  // namespace volumetric_kit::grid::voxelize::detail
